async function moveItem(id,target){const i=items.find(x=>x.id===id);const rows=listItems(i.list_id).filter(x=>!x.done);const from=rows.findIndex(x=>x.id===id),to=rows.findIndex(x=>x.id===target);if(from<0||to<0||from===to)return;rows.splice(to,0,rows.splice(from,1)[0]);try{await action('reorder',{list_id:i.list_id,ids:rows.map(x=>x.id)})}catch(e){handleError(e)}}
function reorderKey(e,id){if(!['ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const rows=listItems(selected).filter(i=>!i.done),pos=rows.findIndex(i=>i.id===id),next=rows[pos+(e.key==='ArrowUp'?-1:1)];if(next)moveItem(id,next.id)}
function startReorder(e,id){if(e.button!==0)return;e.preventDefault();const h=e.currentTarget;h.setPointerCapture(e.pointerId);h.closest('.item').classList.add('dragging');let target=id;const move=ev=>{let distance=Infinity;document.querySelectorAll('#items .item:not(.done)').forEach(r=>{const b=r.getBoundingClientRect(),d=Math.abs(ev.clientY-b.top-b.height/2);r.classList.remove('drop-target');if(d<distance){distance=d;target=r.dataset.id}});if(target!==id)document.querySelector(`[data-id="${target}"]`)?.classList.add('drop-target')};const finish=ev=>{h.removeEventListener('pointermove',move);h.removeEventListener('pointerup',finish);h.removeEventListener('pointercancel',finish);document.querySelectorAll('.dragging,.drop-target').forEach(r=>r.classList.remove('dragging','drop-target'));if(ev.type==='pointerup')moveItem(id,target)};h.addEventListener('pointermove',move);h.addEventListener('pointerup',finish);h.addEventListener('pointercancel',finish)}

let presenceGeneration=0,presenceSignature='';
function startPresence(){
 const l=current();const relevant=members.filter(m=>m.list_id===selected).map(m=>m.user_id);
 const target=user&&view==='lists'&&!passwordMode&&l&&document.visibilityState==='visible'?selected:null;
 const signature=target?[target,user.id,l.owner_id,...relevant.sort()].join(':'):'';
 if(signature===presenceSignature&&(!target||channel)){presencePaint?.();return;}
 presenceSignature=signature;presencePaint=null;const generation=++presenceGeneration;const old=channel;channel=null;
 const container=document.querySelector('.presence');container.innerHTML='';
 if(old)sb.removeChannel(old).catch(()=>{});
 if(!target)return;
 const owner=l.owner_id;const permitted=new Set([owner,...relevant]);const local=sb.channel('mylist-presence:'+target,{config:{presence:{key:user.id}}});channel=local;
 const paint=()=>{
  if(generation!==presenceGeneration||channel!==local)return;
  container.innerHTML=Object.entries(local.presenceState()).filter(([id,states])=>permitted.has(id)&&states.some(s=>s.online)).map(([id])=>{
   const a=accounts.find(a=>a.user_id===id),profile=profiles.find(p=>p.user_id===id);const name=profile?.alias||a?.email||(id===user.id?user.email:'Membru');const initial=avatarInitial(name),color=avatarColor(profile?.color);
   return `<button type="button" class="presence-avatar avatar-${color}" title="${esc(name)} · în această listă" aria-label="${esc(name)} · activ în această listă" onclick="toast(this.title)">${esc(initial)}</button>`;
  }).join('');
 };
 presencePaint=paint;local.on('presence',{event:'sync'},paint);
 local.subscribe(async state=>{
  if(generation!==presenceGeneration||channel!==local)return;
  if(state==='SUBSCRIBED'&&document.visibilityState==='visible')await local.track({online:true});
 });
}
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')load();startPresence()});window.addEventListener('online',()=>load(true).catch(handleError));window.addEventListener('offline',()=>{synced=false;status('Fără conexiune')});
document.addEventListener('input',e=>{const f=e.target;if(f.tagName==='INPUT'&&(!f.type||f.type==='text')){const n=cap(f.value);if(n!==f.value){const p=f.selectionStart;f.value=n;f.setSelectionRange(p,p)}}});
sb.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){passwordSetupRequired=true;setTimeout(()=>startSession(session),0)}else if(event==='SIGNED_OUT')startSession(null);else if(event==='SIGNED_IN'||event==='INITIAL_SESSION')setTimeout(()=>startSession(session),0)});

function listIcon(l){const name=l.name.toLowerCase();const key=l.store||(/lidl/.test(name)?'lidl':/kaufl/.test(name)?'kaufland':/penny/.test(name)?'penny':/atac|auchan/.test(name)?'atac':/doi pa|2 pa/.test(name)?'doi':/pia/.test(name)?'market':/drume/.test(name)?'hike':'custom');const marks={atac:'ATAC',lidl:'LIDL',kaufland:'K',penny:'PENNY',doi:'La Doi<br>Pași',market:'<svg viewBox="0 0 24 24"><path d="M3 10h18l-2-6H5zM5 10v10h14V10M9 20v-6h6v6M3 10c0 3 3 3 4 0 1 3 4 3 5 0 1 3 4 3 5 0 1 3 4 3 4 0"/></svg>',hike:'<svg viewBox="0 0 24 24"><path d="m2 20 7-15 4 8 3-5 6 12zM7 10l2 2 2-2M13 14l3 2 2-2"/></svg>'};return `<span class="store-mark mark-${key}">${marks[key]||esc(l.name.trim().charAt(0).toLocaleUpperCase('ro'))}</span>`}
let refreshing=false,pullStart=null,pullDistance=0,pullTracking=false;
async function refreshData(){
 if(refreshing)return;
 if(busy){toast('Așteaptă finalizarea salvării');return}
 if(!navigator.onLine){toast('Fără conexiune');return}
 if(!user)return;
 refreshing=true;const indicator=$('refreshIndicator');indicator.textContent='Se actualizează…';indicator.classList.add('visible','loading');
 document.querySelectorAll('.refresh-button').forEach(b=>b.disabled=true);
 const scrollTop=window.scrollY;
 try{await load(true);window.scrollTo({top:scrollTop,behavior:'instant'});toast('Actualizat',true)}
 catch(e){handleError(e)}
 finally{refreshing=false;indicator.classList.remove('visible','loading');document.querySelectorAll('.refresh-button').forEach(b=>b.disabled=false)}
}
document.addEventListener('touchstart',e=>{
 pullStart=null;pullDistance=0;pullTracking=false;
 if(!user||refreshing||busy||modal.open||window.scrollY>1||e.touches.length!==1)return;
 if(e.target.closest('input,select,textarea,button,dialog,.cards,.drag-handle'))return;
 pullStart={x:e.touches[0].clientX,y:e.touches[0].clientY};
},{passive:true});
document.addEventListener('touchmove',e=>{
 if(!pullStart||e.touches.length!==1)return;
 const dx=e.touches[0].clientX-pullStart.x,dy=e.touches[0].clientY-pullStart.y;
 if(dy<0||Math.abs(dx)>Math.abs(dy)){pullStart=null;return}
 if(window.scrollY>1){pullStart=null;return}
 if(dy>12){pullTracking=true;pullDistance=dy;if(e.cancelable)e.preventDefault();const indicator=$('refreshIndicator');indicator.classList.add('visible');indicator.textContent=dy>=80?'Eliberează pentru actualizare':'Trage în jos pentru actualizare'}
},{passive:false});
document.addEventListener('touchend',()=>{
 const ready=pullTracking&&pullDistance>=80;
 pullStart=null;pullDistance=0;pullTracking=false;
 if(!refreshing)$('refreshIndicator').classList.remove('visible');
 if(ready)refreshData();
},{passive:true});
document.addEventListener('touchcancel',()=>{pullStart=null;pullDistance=0;pullTracking=false;if(!refreshing)$('refreshIndicator').classList.remove('visible')},{passive:true});

function showPasswordSetup(){if(!user)return;passwordMode=true;startPresence();document.body.dataset.view='auth';$('main').hidden=true;$('loginPanel').hidden=true;$('passwordPanel').hidden=false;$('passwordSetupMessage').textContent='Alege parola pentru conectările viitoare.'}
async function savePassword(e){e.preventDefault();const password=$('newPassword').value,confirm=$('confirmPassword').value,message=$('passwordSetupMessage'),button=e.target.querySelector('button[type="submit"]');if(password!==confirm){message.textContent='Parolele nu coincid.';return}if(password.length<8){message.textContent='Folosește cel puțin 8 caractere.';return}button.disabled=true;message.textContent='Se salvează…';try{const {error}=await sb.auth.updateUser({password});if(error)throw error;passwordSetupRequired=false;try{sessionStorage.removeItem('mylist-password-setup')}catch{}$('newPassword').value='';$('confirmPassword').value='';passwordMode=false;$('passwordPanel').hidden=true;$('main').hidden=false;render();toast('Parola a fost salvată',true)}catch(e){message.textContent=e.code==='same_password'?'Alege o parolă diferită de cea curentă.':e.code==='weak_password'?'Parola este prea slabă. Folosește o combinație mai complexă.':'Parola nu a putut fi salvată. Verifică sesiunea și încearcă din nou.'}finally{button.disabled=false}}

const avatarColors=[['blue','Albastru'],['purple','Violet'],['pink','Roz'],['teal','Verde petrol'],['orange','Portocaliu'],['cyan','Turcoaz'],['gold','Auriu'],['red','Roșu'],['slate','Gri-albăstrui']];
function avatarColor(value){return avatarColors.some(([key])=>key===value)?value:'blue'}
function avatarInitial(name){return Array.from(String(name||'M').trim())[0]?.toLocaleUpperCase('ro')||'M'}
function ownProfile(){return profileDraft||profiles.find(p=>p.user_id===user?.id)||{alias:'',color:'blue'}}
function profileSettings(){const p=ownProfile(),name=p.alias||user.email;return `<div class="settings-section"><h3>Profilul meu</h3><form id="profileForm" class="profile-form" onsubmit="saveProfile(event)"><div class="profile-preview"><span id="profileAvatar" class="presence-avatar avatar-${avatarColor(p.color)}" aria-hidden="true">${esc(avatarInitial(name))}</span><span id="profilePreviewName">${esc(name)}</span></div><label for="profileAlias">Alias</label><input id="profileAlias" type="text" maxlength="30" required autocomplete="nickname" autocapitalize="words" placeholder="De exemplu: Andrei" value="${esc(p.alias)}" oninput="updateProfilePreview()"><fieldset class="avatar-picker"><legend>Culoarea pictogramei</legend><div class="avatar-colors" role="radiogroup" aria-label="Culoarea pictogramei">${avatarColors.map(([key,label])=>`<button type="button" role="radio" class="avatar-swatch avatar-${key}" aria-label="${label}" aria-checked="${avatarColor(p.color)===key}" title="${label}" onclick="chooseAvatarColor('${key}')"><span aria-hidden="true">${avatarColor(p.color)===key?'✓':''}</span></button>`).join('')}</div></fieldset><button class="primary" type="submit" ${profileSaving?'disabled':''}>Salvează profilul</button></form></div>`}
function updateProfilePreview(){const input=$('profileAlias');if(!input)return;const p=ownProfile();profileDraft={alias:input.value,color:avatarColor(p.color)};const name=input.value.trim()||user.email;$('profileAvatar').textContent=avatarInitial(name);$('profilePreviewName').textContent=name}
function chooseAvatarColor(color){if(!avatarColors.some(([key])=>key===color))return;profileDraft={alias:$('profileAlias').value,color};$('profileAvatar').className='presence-avatar avatar-'+color;document.querySelectorAll('.avatar-swatch').forEach((b,i)=>{const active=avatarColors[i][0]===color;b.setAttribute('aria-checked',String(active));b.querySelector('span').textContent=active?'✓':''})}
async function saveProfile(e){e.preventDefault();if(profileSaving||!user)return;const alias=$('profileAlias').value.trim();if(!alias||Array.from(alias).length>30){toast('Completează un alias de maximum 30 de caractere');return}const uid=user.id,color=avatarColor(ownProfile().color),button=e.target.querySelector('button[type="submit"]');profileSaving=true;button.disabled=true;try{const {error}=await sb.from('mylist_profiles').upsert({user_id:uid,alias,color},{onConflict:'user_id'});if(error)throw error;if(user?.id!==uid)return;profileDraft=null;await load(true);toast('Profil salvat',true)}catch(e){handleError(e)}finally{profileSaving=false;button.disabled=false;const currentButton=$('profileForm')?.querySelector('button[type="submit"]');if(currentButton)currentButton.disabled=false}}
